    $block = $lines[$job.line..$end]
    $states = $block | ForEach-Object { $m = [regex]::Match($_, '"'\"state\"\\s*:\\s*\"(["'^"]+)"'"'); if("'$m.Success){$m.Groups[1].Value} }
    $last_state = if($states.Count -gt 0) { $states[-1] } else { "?" }

    if ($last_state -eq "running") {
        $hb = ($block | Where-Object { $_ -like '"'*\"heartbeat_at\"*' } | Select-Object -First 1)
        "'$hb_val = if($hb) { [double]([regex]::Match($hb, '"'\"heartbeat_at\"\\s*:\\s*([\\d.]+)').Groups[1].Value) } else { 0 }
        "'$hb_age = if($hb_val -gt 0) { [int]($now_unix - $hb_val) } else { 999999 }
        $running_jobs += [pscustomobject]@{name=$job.name; hb_age_s=$hb_age; hb_val=$hb_val}
    }
}

Write-Host "Total '"'running' jobs in roster: "'$($running_jobs.Count)"
# Categorize by heartbeat age
$fresh = ($running_jobs | Where-Object { $_.hb_age_s -lt 300 }).Count
$stale = ($running_jobs | Where-Object { $_.hb_age_s -ge 300 }).Count
Write-Host "Fresh (hb < 5min): $fresh"
Write-Host "Stale (hb >= 5min): $stale"'

